'use strict';

// Builds the SELECT statements behind the reporting screens. A screen hands us
// a table, the columns it wants and a set of filters, and whatever comes back
// goes straight to the database driver.

function buildSelect(spec) {
  const columns = spec.columns && spec.columns.length ? spec.columns.join(', ') : '*';
  let text = 'SELECT ' + columns + ' FROM ' + spec.table;
  const parts = [];
  for (const key of Object.keys(spec.where || {})) {
    parts.push(key + " = '" + spec.where[key] + "'");
  }
  if (parts.length) text += ' WHERE ' + parts.join(' AND ');
  if (spec.orderBy) text += ' ORDER BY ' + spec.orderBy;
  if (spec.limit) text += ' LIMIT ' + spec.limit;
  if (spec.offset) text += ' OFFSET ' + spec.offset;
  return { text, values: [] };
}

module.exports = { buildSelect };

