'use strict';

const { buildSelect } = require('./sql.js');

// The reporting screens. Each one turns a request off the HTTP layer into a
// statement and hands it to the driver.

const ITEM_COLUMNS = ['id', 'name', 'qty'];

function itemsForOwner(ownerId) {
  return buildSelect({
    table: 'items',
    columns: ITEM_COLUMNS,
    where: { owner_id: ownerId },
  });
}

module.exports = { itemsForOwner };

