'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { buildSelect, buildUpdate } = require('./src/sql.js');
const { itemsForOwner, searchItems } = require('./src/reports.js');

// A refusal is an Error carrying a short code beside a readable message.
function refuses(fn, code, why) {
  assert.throws(fn, (err) => {
    assert.strictEqual(err.code, code, why + ' (code was ' + String(err && err.code) + ')');
    assert.ok(typeof err.message === 'string' && err.message.length > 0, 'a refusal carries a message');
    return true;
  }, why);
}

test('s1 filter values leave the text and come back as numbered placeholders', () => {
  const built = buildSelect({ table: 'items', columns: ['id', 'name'], where: { owner_id: 7, status: 'live' } });
  assert.ok(/\bWHERE\b/.test(built.text), 'a filtered select still has a WHERE clause');
  assert.ok(/owner_id/.test(built.text), 'the column stays in the text');
  assert.ok(built.text.includes('= $1'), 'the first filter is placeholder one');
  assert.ok(built.text.includes('= $2'), 'the second filter is placeholder two');
  assert.ok(!built.text.includes("'live'"), 'the value never reaches the text');
  assert.ok(!/\b7\b/.test(built.text), 'the value never reaches the text');
  assert.deepStrictEqual(built.values, [7, 'live'], 'the values come back in the order the filters were written');

  const single = buildSelect({ table: 'items', where: { id: 'abc' } });
  assert.ok(single.text.includes('$1'));
  assert.ok(!single.text.includes('abc'), 'the value never reaches the text');
  assert.deepStrictEqual(single.values, ['abc']);

  const unfiltered = buildSelect({ table: 'items', columns: ['id'] });
  assert.ok(!/WHERE/.test(unfiltered.text), 'no filters means no WHERE clause');
  assert.deepStrictEqual(unfiltered.values, []);
});

test('s2 every identifier is quoted and a quote inside a name is doubled', () => {
  const built = buildSelect({ table: 'items', columns: ['id', 'name'], where: { owner_id: 7 } });
  assert.ok(built.text.startsWith('SELECT "id", "name" FROM "items"'), 'table and columns are quoted');
  assert.ok(built.text.includes('"owner_id" = $1'), 'the filter column is quoted too');

  const awkward = buildSelect({ table: 'we"ird', columns: ['a"b'], where: { 'c"d': 1 } });
  assert.ok(awkward.text.startsWith('SELECT "a""b" FROM "we""ird"'), 'a quote inside a name is doubled');
  assert.ok(awkward.text.includes('"c""d" = $1'), 'a quote inside a name is doubled');

  assert.strictEqual(buildSelect({ table: 'items' }).text, 'SELECT * FROM "items"', 'a star is not an identifier');
  assert.strictEqual(buildSelect({ table: 'items', columns: [] }).text, 'SELECT * FROM "items"', 'an empty column list still projects a star');
});

test('s3 a null filter becomes an IS NULL that consumes no placeholder', () => {
  const built = buildSelect({ table: 'items', where: { a: 1, b: null, c: 2 } });
  assert.ok(built.text.includes('"b" IS NULL'), 'null is compared with IS NULL');
  assert.ok(built.text.includes('"a" = $1'));
  assert.ok(built.text.includes('"c" = $2'), 'the numbering closes over the gap the null left');
  assert.ok(!built.text.includes('$3'), 'the null consumed no placeholder');
  assert.deepStrictEqual(built.values, [1, 2]);

  const allNull = buildSelect({ table: 'items', where: { a: null, b: null } });
  assert.strictEqual(allNull.text, 'SELECT * FROM "items" WHERE "a" IS NULL AND "b" IS NULL');
  assert.deepStrictEqual(allNull.values, []);
});

test('s4 an array filter becomes an IN list and the numbering runs across it', () => {
  const built = buildSelect({ table: 'items', where: { a: 1, b: [10, 20, 30], c: 2 } });
  assert.ok(built.text.includes('"b" IN ($2, $3, $4)'), 'one placeholder per element');
  assert.ok(built.text.includes('"a" = $1'));
  assert.ok(built.text.includes('"c" = $5'), 'the filter after the list picks up where the list left off');
  assert.deepStrictEqual(built.values, [1, 10, 20, 30, 2]);

  const one = buildSelect({ table: 'items', where: { a: ['solo'] } });
  assert.ok(one.text.includes('"a" IN ($1)'));
  assert.deepStrictEqual(one.values, ['solo']);

  const empty = buildSelect({ table: 'items', where: { a: [], b: 5 } });
  assert.ok(empty.text.includes('1 = 0'), 'an empty list cannot match anything');
  assert.ok(!empty.text.includes('IN ()'), 'an empty list is never written as an empty IN');
  assert.ok(empty.text.includes('"b" = $1'), 'the empty list consumed no placeholder');
  assert.deepStrictEqual(empty.values, [5]);
});

test('s5 limit and offset are validated whole numbers and zero is a real limit', () => {
  assert.strictEqual(buildSelect({ table: 'items', limit: 10, offset: 20 }).text, 'SELECT * FROM "items" LIMIT 10 OFFSET 20');
  assert.strictEqual(buildSelect({ table: 'items', limit: 0 }).text, 'SELECT * FROM "items" LIMIT 0', 'a limit of zero is a limit, not a missing one');
  assert.strictEqual(buildSelect({ table: 'items', offset: 0 }).text, 'SELECT * FROM "items" OFFSET 0');
  assert.ok(!/LIMIT|OFFSET/.test(buildSelect({ table: 'items' }).text), 'neither clause appears when neither was asked for');

  const nulled = buildSelect({ table: 'items', where: { a: 1 }, limit: null, offset: null });
  assert.strictEqual(nulled.text, 'SELECT * FROM "items" WHERE "a" = $1', 'a null clause is an absent one rather than a bad one');

  const paged = buildSelect({ table: 'items', where: { a: 1 }, limit: 10, offset: 20 });
  assert.strictEqual(paged.text, 'SELECT * FROM "items" WHERE "a" = $1 LIMIT 10 OFFSET 20');
  assert.deepStrictEqual(paged.values, [1], 'a validated whole number is written as digits, not bound through the values array');

  for (const junk of ['10', 2.5, -1, NaN, Infinity, true, {}, []]) {
    refuses(() => buildSelect({ table: 'items', limit: junk }), 'bad_limit', 'an unusable limit is refused rather than guessed at');
    refuses(() => buildSelect({ table: 'items', offset: junk }), 'bad_offset', 'an unusable offset is refused rather than guessed at');
  }
});

test('s6 ORDER BY only accepts columns from the allowlist the screen supplies', () => {
  const sorted = buildSelect({ table: 'items', orderBy: [{ column: 'name' }, { column: 'qty', direction: 'DESC' }], sortable: ['name', 'qty'] });
  assert.strictEqual(sorted.text, 'SELECT * FROM "items" ORDER BY "name" ASC, "qty" DESC', 'sort keys keep their order and default to ascending');

  const lower = buildSelect({ table: 'items', orderBy: [{ column: 'name', direction: 'desc' }], sortable: ['name'] });
  assert.ok(lower.text.includes('ORDER BY "name" DESC'), 'the direction is read whatever its casing');

  const full = buildSelect({ table: 'items', where: { a: 1 }, orderBy: [{ column: 'a' }], sortable: ['a'], limit: 5 });
  assert.strictEqual(full.text, 'SELECT * FROM "items" WHERE "a" = $1 ORDER BY "a" ASC LIMIT 5', 'the sort sits between the filter and the paging');

  assert.ok(!/ORDER BY/.test(buildSelect({ table: 'items', orderBy: [], sortable: ['a'] }).text), 'an empty sort list is no sort at all');

  refuses(() => buildSelect({ table: 'items', orderBy: [{ column: 'password' }], sortable: ['name'] }), 'bad_sort', 'a column outside the allowlist is refused');
  refuses(() => buildSelect({ table: 'items', orderBy: [{ column: 'name' }] }), 'bad_sort', 'with no allowlist nothing is sortable');
  refuses(() => buildSelect({ table: 'items', orderBy: [{ column: 'name', direction: 'sideways' }], sortable: ['name'] }), 'bad_direction', 'a direction is asc or desc');
});

test('s7 the search screen coerces its query string and turns a refusal into a result', () => {
  const basic = searchItems({ owner: 'u1' });
  assert.strictEqual(basic.ok, true);
  assert.strictEqual(basic.statement.text, 'SELECT "id", "name", "qty" FROM "items" WHERE "owner_id" = $1 LIMIT 20 OFFSET 0');
  assert.deepStrictEqual(basic.statement.values, ['u1']);

  const filtered = searchItems({ owner: 'u1', status: 'live' });
  assert.strictEqual(filtered.statement.text, 'SELECT "id", "name", "qty" FROM "items" WHERE "owner_id" = $1 AND "status" = $2 LIMIT 20 OFFSET 0');
  assert.deepStrictEqual(filtered.statement.values, ['u1', 'live']);

  assert.ok(searchItems({ owner: 'u1', sort: 'qty', dir: 'desc' }).statement.text.includes('ORDER BY "qty" DESC'));
  assert.ok(searchItems({ owner: 'u1', sort: 'name' }).statement.text.includes('ORDER BY "name" ASC'));

  assert.ok(searchItems({ owner: 'u1', page: '2', size: '5' }).statement.text.endsWith('LIMIT 5 OFFSET 10'), 'page and size are numbers by the time they reach the builder');
  assert.ok(searchItems({ owner: 'u1', size: '' }).statement.text.endsWith('LIMIT 20 OFFSET 0'), 'an empty query value is a missing one');

  const unsortable = searchItems({ owner: 'u1', sort: 'password' });
  assert.strictEqual(unsortable.ok, false, 'a refusal comes back as a result rather than as a throw');
  assert.strictEqual(unsortable.code, 'bad_sort');

  const badSize = searchItems({ owner: 'u1', size: 'ten' });
  assert.strictEqual(badSize.ok, false);
  assert.strictEqual(badSize.code, 'bad_limit');

  const badPage = searchItems({ owner: 'u1', page: '-1' });
  assert.strictEqual(badPage.ok, false);
  assert.strictEqual(badPage.code, 'bad_offset');

  const badDir = searchItems({ owner: 'u1', sort: 'name', dir: 'sideways' });
  assert.strictEqual(badDir.ok, false, 'any refusal comes back as a result, not only the ones the screen thought of');
  assert.strictEqual(badDir.code, 'bad_direction');

  const untouched = itemsForOwner('u1');
  assert.ok(untouched.text.includes('"owner_id" = $1'), 'the owner screen still builds its own statement');
  assert.deepStrictEqual(untouched.values, ['u1']);
});

test('s8 a filter may name its own operator', () => {
  const above = buildSelect({ table: 'items', where: { qty: { op: '>', value: 5 } } });
  assert.strictEqual(above.text, 'SELECT * FROM "items" WHERE "qty" > $1');
  assert.deepStrictEqual(above.values, [5]);

  const mixed = buildSelect({ table: 'items', where: { a: 1, qty: { op: '<=', value: 9 } } });
  assert.strictEqual(mixed.text, 'SELECT * FROM "items" WHERE "a" = $1 AND "qty" <= $2', 'a bare value still means equality');
  assert.deepStrictEqual(mixed.values, [1, 9]);

  const notNull = buildSelect({ table: 'items', where: { a: { op: '<>', value: null } } });
  assert.strictEqual(notNull.text, 'SELECT * FROM "items" WHERE "a" IS NOT NULL');
  assert.deepStrictEqual(notNull.values, []);
  assert.ok(buildSelect({ table: 'items', where: { a: { op: '=', value: null } } }).text.includes('"a" IS NULL'));

  const notIn = buildSelect({ table: 'items', where: { a: { op: '<>', value: [1, 2] } } });
  assert.strictEqual(notIn.text, 'SELECT * FROM "items" WHERE "a" NOT IN ($1, $2)');
  assert.deepStrictEqual(notIn.values, [1, 2]);

  const excludesNothing = buildSelect({ table: 'items', where: { a: { op: '<>', value: [] }, b: 1 } });
  assert.strictEqual(excludesNothing.text, 'SELECT * FROM "items" WHERE 1 = 1 AND "b" = $1', 'excluding nothing excludes nothing');
  assert.deepStrictEqual(excludesNothing.values, [1]);

  for (const op of ['!=', '==', 'LIKE', 'in', '', null, undefined]) {
    refuses(() => buildSelect({ table: 'items', where: { a: { op: op, value: 1 } } }), 'bad_operator', 'an operator outside the list is refused');
  }
  for (const op of ['<', '<=', '>', '>=']) {
    refuses(() => buildSelect({ table: 'items', where: { a: { op: op, value: null } } }), 'bad_operator', 'only = and <> compare against null');
    refuses(() => buildSelect({ table: 'items', where: { a: { op: op, value: [1] } } }), 'bad_operator', 'only = and <> take a list');
  }
});

test('s9 and and or groups nest, bracket and keep the numbering in reading order', () => {
  assert.strictEqual(buildSelect({ table: 'items', where: { a: 1, b: 2 } }).text,
    'SELECT * FROM "items" WHERE "a" = $1 AND "b" = $2', 'a plain filter object still means AND');

  const either = buildSelect({ table: 'items', where: { or: [{ status: 'live' }, { status: 'draft' }] } });
  assert.strictEqual(either.text, 'SELECT * FROM "items" WHERE "status" = $1 OR "status" = $2', 'the outermost group needs no brackets');
  assert.deepStrictEqual(either.values, ['live', 'draft']);

  const grouped = buildSelect({ table: 'items', where: { or: [{ a: 1, b: 2 }, { c: 3 }] } });
  assert.strictEqual(grouped.text, 'SELECT * FROM "items" WHERE ("a" = $1 AND "b" = $2) OR "c" = $3', 'a two key object inside an or is bracketed');
  assert.deepStrictEqual(grouped.values, [1, 2, 3]);

  const deep = buildSelect({ table: 'items', where: { and: [{ a: 1 }, { or: [{ b: 2 }, { and: [{ c: 3 }, { d: 4 }] }] }] } });
  assert.strictEqual(deep.text, 'SELECT * FROM "items" WHERE "a" = $1 AND ("b" = $2 OR ("c" = $3 AND "d" = $4))');
  assert.deepStrictEqual(deep.values, [1, 2, 3, 4], 'left to right, depth first');

  const composed = buildSelect({ table: 'items', where: { or: [{ a: [1, 2] }, { b: null }, { c: { op: '>', value: 3 } }] } });
  assert.strictEqual(composed.text, 'SELECT * FROM "items" WHERE "a" IN ($1, $2) OR "b" IS NULL OR "c" > $3');
  assert.deepStrictEqual(composed.values, [1, 2, 3]);

  const whole = buildSelect({ table: 'items', where: { or: [{ a: 1 }, { b: 2 }] }, orderBy: [{ column: 'a' }], sortable: ['a'], limit: 5, offset: 5 });
  assert.strictEqual(whole.text, 'SELECT * FROM "items" WHERE "a" = $1 OR "b" = $2 ORDER BY "a" ASC LIMIT 5 OFFSET 5');

  refuses(() => buildSelect({ table: 'items', where: { or: [] } }), 'bad_group', 'an empty group is refused');
  refuses(() => buildSelect({ table: 'items', where: { and: [] } }), 'bad_group', 'an empty group is refused');
  refuses(() => buildSelect({ table: 'items', where: { and: [{ a: 1 }, { or: [] }] } }), 'bad_group', 'an empty group nested inside a good one is refused');
});

test('s10 a text search escapes the wildcards the user typed', () => {
  const starts = buildSelect({ table: 'items', where: { name: { op: 'startsWith', value: 'ab' } } });
  assert.strictEqual(starts.text, 'SELECT * FROM "items" WHERE "name" LIKE $1 ESCAPE \'\\\'');
  assert.deepStrictEqual(starts.values, ['ab%']);

  const has = buildSelect({ table: 'items', where: { name: { op: 'contains', value: 'ab' } } });
  assert.strictEqual(has.text, 'SELECT * FROM "items" WHERE "name" LIKE $1 ESCAPE \'\\\'');
  assert.deepStrictEqual(has.values, ['%ab%']);

  const wild = buildSelect({ table: 'items', where: { name: { op: 'startsWith', value: '50%_off' } } });
  assert.deepStrictEqual(wild.values, ['50\\%\\_off%'], 'the per cent and the underscore the user typed are literals');
  assert.ok(!wild.text.includes('50'), 'the pattern never reaches the text');

  const slashes = buildSelect({ table: 'items', where: { name: { op: 'contains', value: 'a\\b%c' } } });
  assert.deepStrictEqual(slashes.values, ['%a\\\\b\\%c%'], 'the backslash is escaped before the wildcards are');

  const composed = buildSelect({ table: 'items', where: { or: [{ name: { op: 'contains', value: 'x' } }, { a: 1 }] } });
  assert.strictEqual(composed.text, 'SELECT * FROM "items" WHERE "name" LIKE $1 ESCAPE \'\\\' OR "a" = $2');
  assert.deepStrictEqual(composed.values, ['%x%', 1]);

  for (const junk of [5, null, undefined, [], {}, true]) {
    refuses(() => buildSelect({ table: 'items', where: { name: { op: 'startsWith', value: junk } } }), 'bad_pattern', 'a text search needs text');
    refuses(() => buildSelect({ table: 'items', where: { name: { op: 'contains', value: junk } } }), 'bad_pattern', 'a text search needs text');
  }
});

test('s11 identifiers may be qualified, have to be real, and one refusal outranks another', () => {
  const qualified = buildSelect({ table: 'reporting.items', columns: ['items.id'], where: { 'items.owner_id': 7 } });
  assert.strictEqual(qualified.text, 'SELECT "items"."id" FROM "reporting"."items" WHERE "items"."owner_id" = $1', 'each part of a dotted name is quoted on its own');
  assert.strictEqual(buildSelect({ table: 'we"ird.tab' }).text, 'SELECT * FROM "we""ird"."tab"', 'quoting and splitting compose');
  assert.ok(buildSelect({ table: 'items', orderBy: [{ column: 'items.qty', direction: 'desc' }], sortable: ['items.qty'] }).text
    .includes('ORDER BY "items"."qty" DESC'), 'a sort column may be qualified too');

  for (const bad of ['', '   ', 'a..b', '.a', 'a.', 5, null, undefined, {}]) {
    refuses(() => buildSelect({ table: bad }), 'bad_identifier', 'a table name has to be a real identifier');
    refuses(() => buildSelect({ table: 'items', columns: [bad] }), 'bad_identifier', 'a projected column has to be a real identifier');
  }
  for (const bad of ['', '   ', 'a..b', '.a', 'a.']) {
    const where = {};
    where[bad] = 1;
    refuses(() => buildSelect({ table: 'items', where: where }), 'bad_identifier', 'a filter column has to be a real identifier');
  }
  refuses(() => buildSelect({ table: 'items', orderBy: [{ column: 'a..b' }], sortable: ['a..b'] }),
    'bad_identifier', 'a sort column has to be a real identifier even where the allowlist names it');
  refuses(() => buildSelect({ table: 'items', orderBy: [{ column: '   ' }], sortable: ['a'] }),
    'bad_identifier', 'bad_identifier outranks bad_sort on a sort column');

  refuses(() => buildSelect({ table: 'items', where: { and: [{ a: { op: '!!', value: 1 } }, { '': 2 }] } }),
    'bad_identifier', 'bad_identifier outranks bad_operator wherever each one sits');
  refuses(() => buildSelect({ table: 'items', where: { and: [{ or: [] }, { a: { op: '!!', value: 1 } }] } }),
    'bad_operator', 'bad_operator outranks bad_group');
  refuses(() => buildSelect({ table: 'items', where: { and: [{ a: { op: 'contains', value: 5 } }, { b: { op: '!!', value: 1 } }] } }),
    'bad_operator', 'bad_operator outranks bad_pattern');
  refuses(() => buildSelect({ table: 'items', where: { and: [{ or: [] }, { a: { op: 'contains', value: 5 } }] } }),
    'bad_pattern', 'bad_pattern outranks bad_group');
  refuses(() => buildSelect({ table: 'items', where: { or: [] }, orderBy: [{ column: 'nope' }], sortable: ['a'] }),
    'bad_group', 'bad_group outranks bad_sort');
  refuses(() => buildSelect({ table: 'items', orderBy: [{ column: 'nope', direction: 'sideways' }], sortable: ['a'] }),
    'bad_sort', 'bad_sort outranks bad_direction');
  refuses(() => buildSelect({ table: 'items', orderBy: [{ column: 'a', direction: 'sideways' }], sortable: ['a'], limit: -1 }),
    'bad_direction', 'bad_direction outranks bad_limit');
  refuses(() => buildSelect({ table: 'items', limit: '5', offset: '5' }), 'bad_limit', 'bad_limit outranks bad_offset');
  refuses(() => buildSelect({ table: '', orderBy: [{ column: 'nope' }], sortable: ['a'], limit: -1 }),
    'bad_identifier', 'bad_identifier outranks everything after it');
});

test('s12 buildUpdate numbers its assignments before its filters', () => {
  const built = buildUpdate({ table: 'items', set: { name: 'x', qty: 3 }, where: { owner_id: 7 } });
  assert.strictEqual(built.text, 'UPDATE "items" SET "name" = $1, "qty" = $2 WHERE "owner_id" = $3');
  assert.deepStrictEqual(built.values, ['x', 3, 7]);

  const nulls = buildUpdate({ table: 'items', set: { a: null }, where: { b: null } });
  assert.strictEqual(nulls.text, 'UPDATE "items" SET "a" = $1 WHERE "b" IS NULL', 'a null assignment is a value, a null filter is an IS NULL');
  assert.deepStrictEqual(nulls.values, [null]);

  const grouped = buildUpdate({ table: 'items', set: { x: 1 }, where: { or: [{ a: 2 }, { b: [3, 4] }] } });
  assert.strictEqual(grouped.text, 'UPDATE "items" SET "x" = $1 WHERE "a" = $2 OR "b" IN ($3, $4)', 'the where the select builder understands is the where this one understands');
  assert.deepStrictEqual(grouped.values, [1, 2, 3, 4]);

  const awkward = buildUpdate({ table: 'reporting.items', set: { 'we"ird': 1 }, where: { id: 2 } });
  assert.strictEqual(awkward.text, 'UPDATE "reporting"."items" SET "we""ird" = $1 WHERE "id" = $2');

  const quoted = buildUpdate({ table: 'items', set: { name: "O'Brien" }, where: { id: 2 } });
  assert.ok(!quoted.text.includes('Brien'), 'the value never reaches the text');
  assert.deepStrictEqual(quoted.values, ["O'Brien", 2]);

  refuses(() => buildUpdate({ table: 'items', set: {}, where: { a: 1 } }), 'bad_update', 'an update with nothing to set is refused');
  refuses(() => buildUpdate({ table: 'items', set: { a: 1 } }), 'bad_update', 'an update with no filter is refused');
  refuses(() => buildUpdate({ table: 'items', set: { a: 1 }, where: {} }), 'bad_update', 'an update whose filter holds nothing is refused');
  refuses(() => buildUpdate({ table: 'items', set: { '': 1 }, where: { a: 1 } }), 'bad_identifier', 'the identifier rules cover the set columns');

  refuses(() => buildUpdate({ table: '', set: {}, where: {} }),
    'bad_identifier', 'the identifier rules outrank the update check');
  refuses(() => buildUpdate({ table: 'items', set: {}, where: { a: { op: '!!', value: 1 } } }),
    'bad_operator', 'the operator rules outrank the update check');
  refuses(() => buildUpdate({ table: 'items', set: {}, where: { and: [] } }),
    'bad_group', 'the group rule outranks the update check');
});

