'use strict';

// Builds the statements behind the reporting screens. Nothing a caller supplies
// as a value ever reaches the text: values leave through the values array as
// numbered placeholders, and identifiers are quoted rather than pasted.

const COMPARISONS = ['=', '<>', '<', '<=', '>', '>='];
const SET_COMPARISONS = ['=', '<>'];
const PATTERN_OPS = ['startsWith', 'contains'];

function refuse(code, message) {
  const err = new Error(message);
  err.code = code;
  return err;
}

function isWholeCount(value) {
  return typeof value === 'number' && Number.isInteger(value) && value >= 0;
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function hasOwn(obj, key) {
  return Object.prototype.hasOwnProperty.call(obj, key);
}

function isGroup(node) {
  return isPlainObject(node) && (hasOwn(node, 'and') || hasOwn(node, 'or'));
}

function groupList(node) {
  return hasOwn(node, 'and') ? node.and : node.or;
}

// A name may be qualified, and every part of it has to be a real one.
function isIdentifier(name) {
  if (typeof name !== 'string') return false;
  return name.split('.').every((part) => part.trim().length > 0);
}

function quoteIdentifier(name) {
  return name
    .split('.')
    .map((part) => '"' + part.replace(/"/g, '""') + '"')
    .join('.');
}

// A filter entry is either a bare value or an { op, value } pair.
function conditionFrom(column, raw) {
  if (isPlainObject(raw) && hasOwn(raw, 'op')) {
    return { column, op: raw.op, value: raw.value };
  }
  return { column, op: '=', value: raw };
}

// Depth first, left to right: the order the placeholders are numbered in, and
// the order the validation passes read the tree in.
function collect(node, found) {
  if (isGroup(node)) {
    const list = groupList(node);
    if (!Array.isArray(list) || list.length === 0) {
      found.badGroup = true;
      return found;
    }
    for (const child of list) collect(child, found);
    return found;
  }
  if (isPlainObject(node)) {
    for (const key of Object.keys(node)) found.conditions.push(conditionFrom(key, node[key]));
    return found;
  }
  found.badGroup = true;
  return found;
}

function collectWhere(where) {
  const found = { conditions: [], badGroup: false };
  if (where === undefined || where === null) return found;
  return collect(where, found);
}

function sortEntries(orderBy) {
  return Array.isArray(orderBy) ? orderBy : [];
}

// The refusal order is load bearing, so each rule gets its own pass over the
// whole spec rather than being raised where the tree walk happens to reach it.
function checkIdentifiers(names) {
  for (const name of names) {
    if (!isIdentifier(name)) {
      throw refuse('bad_identifier', 'not a usable identifier: ' + String(name));
    }
  }
}

function checkConditions(found) {
  for (const cond of found.conditions) {
    if (PATTERN_OPS.indexOf(cond.op) !== -1) continue;
    if (COMPARISONS.indexOf(cond.op) === -1) {
      throw refuse('bad_operator', 'not an operator this builder writes: ' + String(cond.op));
    }
    const wholeSet = cond.value === null || Array.isArray(cond.value);
    if (wholeSet && SET_COMPARISONS.indexOf(cond.op) === -1) {
      throw refuse('bad_operator', 'the operator ' + cond.op + ' has no statement for that value');
    }
  }
  for (const cond of found.conditions) {
    if (PATTERN_OPS.indexOf(cond.op) !== -1 && typeof cond.value !== 'string') {
      throw refuse('bad_pattern', 'a text search needs a string to search for');
    }
  }
  if (found.badGroup) {
    throw refuse('bad_group', 'a group needs at least one condition inside it');
  }
}

function checkSort(spec) {
  if (spec.orderBy === undefined || spec.orderBy === null) return;
  if (!Array.isArray(spec.orderBy)) {
    throw refuse('bad_sort', 'orderBy is a list of sort keys');
  }
  const allowed = Array.isArray(spec.sortable) ? spec.sortable : [];
  for (const entry of spec.orderBy) {
    const column = isPlainObject(entry) ? entry.column : entry;
    if (allowed.indexOf(column) === -1) {
      throw refuse('bad_sort', 'not a sortable column: ' + String(column));
    }
  }
  for (const entry of spec.orderBy) {
    const direction = isPlainObject(entry) ? entry.direction : undefined;
    if (direction === undefined) continue;
    if (typeof direction !== 'string' || !/^(asc|desc)$/i.test(direction)) {
      throw refuse('bad_direction', 'a sort direction is asc or desc: ' + String(direction));
    }
  }
}

function checkPaging(spec) {
  if (spec.limit !== undefined && spec.limit !== null && !isWholeCount(spec.limit)) {
    throw refuse('bad_limit', 'limit must be a whole number of zero or more');
  }
  if (spec.offset !== undefined && spec.offset !== null && !isWholeCount(spec.offset)) {
    throw refuse('bad_offset', 'offset must be a whole number of zero or more');
  }
}

function place(state, value) {
  state.values.push(value);
  return '$' + state.values.length;
}

// The wildcards a user typed are literals, so the backslash goes first and the
// two wildcard characters follow it.
function escapeForLike(text) {
  return text.replace(/\\/g, '\\\\').replace(/%/g, '\\%').replace(/_/g, '\\_');
}

function renderCondition(cond, state) {
  const column = quoteIdentifier(cond.column);
  if (PATTERN_OPS.indexOf(cond.op) !== -1) {
    const body = escapeForLike(cond.value);
    const pattern = cond.op === 'startsWith' ? body + '%' : '%' + body + '%';
    return column + ' LIKE ' + place(state, pattern) + " ESCAPE '\\'";
  }
  if (cond.value === null) {
    return column + (cond.op === '=' ? ' IS NULL' : ' IS NOT NULL');
  }
  if (Array.isArray(cond.value)) {
    if (cond.value.length === 0) return cond.op === '=' ? '1 = 0' : '1 = 1';
    const marks = cond.value.map((item) => place(state, item)).join(', ');
    return column + (cond.op === '=' ? ' IN (' : ' NOT IN (') + marks + ')';
  }
  return column + ' ' + cond.op + ' ' + place(state, cond.value);
}

function renderNode(node, state, outermost) {
  let parts;
  let joiner;
  if (isGroup(node)) {
    joiner = hasOwn(node, 'and') ? ' AND ' : ' OR ';
    parts = groupList(node).map((child) => renderNode(child, state, false));
  } else {
    joiner = ' AND ';
    parts = Object.keys(node).map((key) => renderCondition(conditionFrom(key, node[key]), state));
  }
  const joined = parts.join(joiner);
  return parts.length > 1 && !outermost ? '(' + joined + ')' : joined;
}

function renderWhere(where, state) {
  if (where === undefined || where === null) return '';
  return renderNode(where, state, true);
}

function renderSort(orderBy) {
  const entries = sortEntries(orderBy);
  if (entries.length === 0) return '';
  return entries
    .map((entry) => {
      const direction = entry.direction === undefined ? 'ASC' : String(entry.direction).toUpperCase();
      return quoteIdentifier(entry.column) + ' ' + direction;
    })
    .join(', ');
}

function buildSelect(spec) {
  const s = isPlainObject(spec) ? spec : {};
  const found = collectWhere(s.where);
  const columns = Array.isArray(s.columns) ? s.columns : [];
  const sortColumns = sortEntries(s.orderBy).map((entry) => (isPlainObject(entry) ? entry.column : entry));

  checkIdentifiers([s.table].concat(columns, found.conditions.map((cond) => cond.column), sortColumns));
  checkConditions(found);
  checkSort(s);
  checkPaging(s);

  const state = { values: [] };
  const projection = columns.length ? columns.map(quoteIdentifier).join(', ') : '*';
  let text = 'SELECT ' + projection + ' FROM ' + quoteIdentifier(s.table);
  const where = renderWhere(s.where, state);
  if (where) text += ' WHERE ' + where;
  const sort = renderSort(s.orderBy);
  if (sort) text += ' ORDER BY ' + sort;
  if (s.limit !== undefined && s.limit !== null) text += ' LIMIT ' + s.limit;
  if (s.offset !== undefined && s.offset !== null) text += ' OFFSET ' + s.offset;
  return { text, values: state.values };
}

function buildUpdate(spec) {
  const s = isPlainObject(spec) ? spec : {};
  const assignments = isPlainObject(s.set) ? Object.keys(s.set) : [];
  const found = collectWhere(s.where);

  checkIdentifiers([s.table].concat(assignments, found.conditions.map((cond) => cond.column)));
  checkConditions(found);
  if (assignments.length === 0) {
    throw refuse('bad_update', 'an update needs at least one assignment');
  }
  if (found.conditions.length === 0) {
    throw refuse('bad_update', 'an update needs a where of its own');
  }

  // In a SET clause a null is an ordinary value bound to a placeholder; only
  // in a WHERE does it mean IS NULL.
  const state = { values: [] };
  const sets = assignments
    .map((key) => quoteIdentifier(key) + ' = ' + place(state, s.set[key]))
    .join(', ');
  const text = 'UPDATE ' + quoteIdentifier(s.table) + ' SET ' + sets + ' WHERE ' + renderWhere(s.where, state);
  return { text, values: state.values };
}

module.exports = { buildSelect, buildUpdate };

