'use strict';

const { buildSelect } = require('./sql.js');

// The reporting screens. Each one turns a request off the HTTP layer into a
// statement and hands it to the driver.

const ITEM_COLUMNS = ['id', 'name', 'qty'];

function itemsForOwner(ownerId) {
  return buildSelect({
    table: 'items',
    columns: ITEM_COLUMNS,
    where: { owner_id: ownerId },
  });
}

// Query string fields arrive as strings or not at all, and an empty value is
// the same as a missing one.
function field(query, name) {
  const raw = isObject(query) ? query[name] : undefined;
  if (raw === undefined || raw === null) return undefined;
  const text = String(raw).trim();
  return text === '' ? undefined : text;
}

function isObject(value) {
  return value !== null && typeof value === 'object';
}

function searchItems(query) {
  const rawSize = field(query, 'size');
  const rawPage = field(query, 'page');
  const size = rawSize === undefined ? 20 : Number(rawSize);
  const page = rawPage === undefined ? 0 : Number(rawPage);

  const where = {};
  const owner = field(query, 'owner');
  if (owner !== undefined) where.owner_id = owner;
  const status = field(query, 'status');
  if (status !== undefined) where.status = status;

  const spec = {
    table: 'items',
    columns: ITEM_COLUMNS,
    where,
    sortable: ITEM_COLUMNS,
    limit: size,
    offset: page * size,
  };
  const sort = field(query, 'sort');
  if (sort !== undefined) spec.orderBy = [{ column: sort, direction: field(query, 'dir') }];

  try {
    return { ok: true, statement: buildSelect(spec) };
  } catch (err) {
    if (err && err.code) return { ok: false, code: err.code };
    throw err;
  }
}

module.exports = { itemsForOwner, searchItems };
